/**
 * Binary writer for .riv file format
 * Implements varuint encoding and other primitives used by Rive
 */
export class BinaryWriter {
    buffer = [];
    /**
     * Write a variable-length unsigned integer (LEB128 encoding)
     * Used for object types, property keys, and other integers
     */
    writeVarUint(value) {
        if (value < 0) {
            throw new Error('writeVarUint: value must be non-negative');
        }
        do {
            let byte = value & 0x7f;
            value >>>= 7;
            if (value !== 0) {
                byte |= 0x80; // Set continuation bit
            }
            this.buffer.push(byte);
        } while (value !== 0);
    }
    /**
     * Write a raw byte
     */
    writeByte(value) {
        this.buffer.push(value & 0xff);
    }
    /**
     * Write raw bytes
     */
    writeBytes(bytes) {
        for (const byte of bytes) {
            this.buffer.push(byte & 0xff);
        }
    }
    /**
     * Write a 32-bit float (little-endian)
     */
    writeFloat(value) {
        const buf = new ArrayBuffer(4);
        const view = new DataView(buf);
        view.setFloat32(0, value, true); // little-endian
        for (let i = 0; i < 4; i++) {
            this.buffer.push(view.getUint8(i));
        }
    }
    /**
     * Write a 64-bit double (little-endian)
     */
    writeDouble(value) {
        const buf = new ArrayBuffer(8);
        const view = new DataView(buf);
        view.setFloat64(0, value, true); // little-endian
        for (let i = 0; i < 8; i++) {
            this.buffer.push(view.getUint8(i));
        }
    }
    /**
     * Write a string (length-prefixed with varuint)
     */
    writeString(value) {
        const encoder = new TextEncoder();
        const bytes = encoder.encode(value);
        this.writeVarUint(bytes.length);
        this.writeBytes(bytes);
    }
    /**
     * Write a 32-bit unsigned integer (little-endian)
     */
    writeUint32(value) {
        this.buffer.push(value & 0xff);
        this.buffer.push((value >> 8) & 0xff);
        this.buffer.push((value >> 16) & 0xff);
        this.buffer.push((value >> 24) & 0xff);
    }
    /**
     * Write a boolean as a single byte
     */
    writeBool(value) {
        this.buffer.push(value ? 1 : 0);
    }
    /**
     * Write a color as 4 bytes (RGBA)
     */
    writeColor(value) {
        this.writeUint32(value);
    }
    /**
     * Get the current buffer as Uint8Array
     */
    toUint8Array() {
        return new Uint8Array(this.buffer);
    }
    /**
     * Get the current buffer length
     */
    get length() {
        return this.buffer.length;
    }
    /**
     * Clear the buffer
     */
    clear() {
        this.buffer = [];
    }
}
